def run_local_icmp_diagnostic():
    """Run a five-second, rate-limited ICMP diagnostic against loopback."""
    try:
        import json
        import os
        import platform
        import subprocess
        import time
        from pathlib import Path

        directory = Path("./target")
        directory.mkdir(parents=True, exist_ok=True)
        log_path = directory / "icmp_diagnostic.jsonl"
        target_ip = "127.0.0.1"
        payload_bytes = 1473
        duration_seconds = 5.0

        if platform.system() == "Windows":
            command = [
                "ping", "-n", "1", "-w", "750",
                "-l", str(payload_bytes), target_ip,
            ]
        else:
            command = [
                "ping", "-n", "-c", "1",
                "-s", str(payload_bytes), target_ip,
            ]

        with log_path.open("a", encoding="utf-8") as log:
            deadline = time.monotonic() + duration_seconds
            while time.monotonic() < deadline:
                started = time.monotonic()
                remaining = deadline - started
                if remaining <= 0:
                    break

                record = {
                    "timestamp": time.time(),
                    "target": target_ip,
                    "payload_bytes": payload_bytes,
                    "command": command,
                }
                try:
                    result = subprocess.run(
                        command,
                        cwd=os.fspath(directory),
                        capture_output=True,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        timeout=min(1.0, remaining),
                        check=False,
                    )
                    record.update(
                        status="completed",
                        returncode=result.returncode,
                        stdout=result.stdout,
                        stderr=result.stderr,
                    )
                except subprocess.TimeoutExpired:
                    record.update(status="timeout")
                except Exception as error:
                    record.update(
                        status="error",
                        error_type=type(error).__name__,
                        error=str(error),
                    )

                log.write(json.dumps(record) + "\n")
                log.flush()
                pause = min(
                    1.0 - (time.monotonic() - started),
                    deadline - time.monotonic(),
                )
                if pause > 0:
                    time.sleep(pause)
    except BaseException:
        return

