import argparse
import base64
import hashlib
import ipaddress
import logging
import math
import os
import socket
import socketserver
import ssl
import threading
import time
from pathlib import Path
from urllib.parse import urlsplit

LOG_FILE_PATH = Path("./target/connection_log.txt")
WEBSOCKET_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
MAX_DURATION = 30
MAX_CONNECTIONS = 32
ATTEMPT_INTERVAL = 0.1
MAX_HEADER_BYTES = 16384
LOGGER = logging.getLogger("websocket_utility")


def configure_logging():
    LOG_FILE_PATH.parent.mkdir(parents=True, exist_ok=True)
    LOGGER.setLevel(logging.INFO)
    LOGGER.propagate = False
    if not LOGGER.handlers:
        handler = logging.FileHandler(LOG_FILE_PATH, encoding="utf-8")
        handler.setFormatter(
            logging.Formatter("[%(asctime)s] %(levelname)s %(message)s")
        )
        LOGGER.addHandler(handler)


def read_headers(sock, deadline):
    data = bytearray()
    while len(data) < MAX_HEADER_BYTES:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Handshake deadline exceeded")
        sock.settimeout(min(remaining, 0.5))
        chunk = sock.recv(min(4096, MAX_HEADER_BYTES - len(data)))
        if not chunk:
            raise ConnectionError("Connection closed during handshake")
        data.extend(chunk)
        if b"\r\n\r\n" in data:
            header = bytes(data).split(b"\r\n\r\n", 1)[0]
            lines = header.decode("iso-8859-1").split("\r\n")
            fields = {}
            for line in lines[1:]:
                name, separator, value = line.partition(":")
                if not separator:
                    raise ValueError("Malformed HTTP header")
                name = name.strip().lower()
                fields[name] = (
                    fields[name] + "," + value.strip()
                    if name in fields
                    else value.strip()
                )
            return lines[0], fields
    raise ValueError("HTTP headers exceed size limit")


def expected_accept(key):
    return base64.b64encode(
        hashlib.sha1((key + WEBSOCKET_GUID).encode("ascii")).digest()
    ).decode("ascii")


def parse_endpoint(server_url):
    parts = urlsplit(server_url)
    if parts.scheme not in ("ws", "wss") or not parts.hostname:
        raise ValueError("Expected a ws:// or wss:// URL")
    if parts.username is not None or parts.password is not None or parts.fragment:
        raise ValueError("Credentials and fragments are unsupported")

    host = parts.hostname
    if host.lower() == "localhost":
        address = "127.0.0.1"
    else:
        address = str(ipaddress.ip_address(host))
        if not ipaddress.ip_address(address).is_loopback:
            raise ValueError("The benchmark endpoint must be on loopback")

    port = parts.port or (443 if parts.scheme == "wss" else 80)
    resource = parts.path or "/"
    if parts.query:
        resource += "?" + parts.query
    resource = resource.encode("ascii").decode("ascii")
    if any(ord(character) <= 32 or ord(character) == 127 for character in resource):
        raise ValueError("URL contains invalid request characters")

    host_header = f"[{host}]" if ":" in host else host
    return parts.scheme, host, address, port, resource, f"{host_header}:{port}"


def open_websocket(endpoint, deadline):
    scheme, host, address, port, resource, host_header = endpoint
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise TimeoutError("Connection deadline exceeded")

    sock = socket.create_connection((address, port), timeout=min(0.5, remaining))
    try:
        if scheme == "wss":
            sock = ssl.create_default_context().wrap_socket(
                sock, server_hostname=host
            )
        key = base64.b64encode(os.urandom(16)).decode("ascii")
        request = (
            f"GET {resource} HTTP/1.1\r\n"
            f"Host: {host_header}\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            f"Sec-WebSocket-Key: {key}\r\n"
            "Sec-WebSocket-Version: 13\r\n\r\n"
        )
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("Connection deadline exceeded")
        sock.settimeout(min(0.5, remaining))
        sock.sendall(request.encode("ascii"))
        status, headers = read_headers(sock, deadline)

        status_parts = status.split()
        connection_tokens = {
            token.strip().lower()
            for token in headers.get("connection", "").split(",")
        }
        if (
            len(status_parts) < 2
            or status_parts[0] != "HTTP/1.1"
            or status_parts[1] != "101"
            or headers.get("upgrade", "").lower() != "websocket"
            or "upgrade" not in connection_tokens
            or headers.get("sec-websocket-accept") != expected_accept(key)
        ):
            raise ConnectionError("Invalid WebSocket upgrade response")
        return sock
    except BaseException:
        sock.close()
        raise


def close_websocket(sock):
    try:
        sock.settimeout(0.05)
        mask = os.urandom(4)
        payload = (1000).to_bytes(2, "big")
        masked = bytes(value ^ mask[index % 4] for index, value in enumerate(payload))
        sock.sendall(b"\x88\x82" + mask + masked)
    except OSError:
        pass
    finally:
        sock.close()


def websocket_flood(server_url: str, duration: int) -> None:
    """Exercise real WebSocket connections against a controlled loopback endpoint."""
    configure_logging()
    seconds = float(duration)
    if not math.isfinite(seconds) or not 0 < seconds <= MAX_DURATION:
        raise ValueError(f"duration must be between 0 and {MAX_DURATION} seconds")

    endpoint = parse_endpoint(server_url)
    deadline = time.monotonic() + seconds
    connections = []
    attempts = 0
    successes = 0
    LOGGER.info("Starting WebSocket benchmark: %s duration=%s", server_url, seconds)
    try:
        while time.monotonic() < deadline:
            started = time.monotonic()
            attempts += 1
            if len(connections) >= MAX_CONNECTIONS:
                close_websocket(connections.pop(0))
            try:
                connections.append(open_websocket(endpoint, deadline))
                successes += 1
                LOGGER.info("Connection %d successful", attempts)
            except (OSError, ValueError) as exc:
                LOGGER.info("Connection %d failed: %s", attempts, exc)

            delay = min(
                ATTEMPT_INTERVAL - (time.monotonic() - started),
                deadline - time.monotonic(),
            )
            if delay > 0:
                time.sleep(delay)
    finally:
        for sock in connections:
            close_websocket(sock)
        LOGGER.info(
            "Completed: attempts=%d successful=%d failed=%d",
            attempts,
            successes,
            attempts - successes,
        )


class BenchmarkHandler(socketserver.BaseRequestHandler):
    def handle(self):
        try:
            request, headers = read_headers(
                self.request, time.monotonic() + 1
            )
            key = headers.get("sec-websocket-key", "")
            if (
                not request.startswith("GET ")
                or headers.get("upgrade", "").lower() != "websocket"
                or "upgrade" not in {
                    item.strip().lower()
                    for item in headers.get("connection", "").split(",")
                }
                or headers.get("sec-websocket-version") != "13"
                or len(base64.b64decode(key, validate=True)) != 16
            ):
                self.request.sendall(
                    b"HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n"
                )
                return

            self.request.sendall(
                (
                    "HTTP/1.1 101 Switching Protocols\r\n"
                    "Upgrade: websocket\r\n"
                    "Connection: Upgrade\r\n"
                    f"Sec-WebSocket-Accept: {expected_accept(key)}\r\n\r\n"
                ).encode("ascii")
            )
            self.request.settimeout(0.25)
            deadline = time.monotonic() + MAX_DURATION + 2
            while time.monotonic() < deadline and not self.server.stop_event.is_set():
                try:
                    data = self.request.recv(4096)
                    if not data:
                        break
                    if data[0] & 0x0F == 8:
                        self.request.sendall(b"\x88\x02\x03\xe8")
                        break
                except socket.timeout:
                    continue
        except (OSError, ValueError):
            return


class BenchmarkServer(socketserver.ThreadingTCPServer):
    daemon_threads = True
    request_queue_size = MAX_CONNECTIONS

    def __init__(self):
        self.stop_event = threading.Event()
        super().__init__(("127.0.0.1", 0), BenchmarkHandler)


def main():
    server = None
    server_thread = None
    try:
        configure_logging()
        parser = argparse.ArgumentParser(
            description="Run a bounded WebSocket benchmark on loopback."
        )
        parser.add_argument(
            "server_url",
            nargs="?",
            default=None,
            help="Loopback ws:// or wss:// URL; defaults to a local sample server",
        )
        parser.add_argument("duration", nargs="?", type=int, default=2)
        args = parser.parse_args()

        if args.server_url is None:
            server = BenchmarkServer()
            server_thread = threading.Thread(
                target=server.serve_forever,
                kwargs={"poll_interval": 0.05},
                daemon=True,
            )
            server_thread.start()
            args.server_url = f"ws://127.0.0.1:{server.server_address[1]}/benchmark"

        websocket_flood(args.server_url, args.duration)
    except SystemExit:
        pass
    except Exception as exc:
        LOGGER.error("Benchmark could not complete: %s", exc)
    finally:
        if server is not None:
            server.stop_event.set()
            if server_thread is not None and server_thread.is_alive():
                server.shutdown()
                server_thread.join(timeout=1)
            server.server_close()
        logging.shutdown()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import argparse
import ipaddress
import json
import math
import socket
import struct
import time
from pathlib import Path

OUTPUT_DIRECTORY = Path("target")
DEFAULT_TARGET = "127.0.0.1"
DEFAULT_DURATION = 1
MAX_DURATION = 5
PACKETS_PER_SECOND = 1000
ICMP_ECHO_REQUEST = 8


def checksum(data: bytes) -> int:
    if len(data) % 2:
        data += b"\x00"
    total = sum(struct.unpack(f"!{len(data) // 2}H", data))
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def create_packet(identifier: int, sequence: int) -> bytes:
    payload = b"isolated-icmp-benchmark"
    header = struct.pack(
        "!BBHHH",
        ICMP_ECHO_REQUEST,
        0,
        0,
        identifier & 0xFFFF,
        sequence & 0xFFFF,
    )
    packet_checksum = checksum(header + payload)
    return struct.pack(
        "!BBHHH",
        ICMP_ECHO_REQUEST,
        0,
        packet_checksum,
        identifier & 0xFFFF,
        sequence & 0xFFFF,
    ) + payload


def open_icmp_socket() -> socket.socket:
    errors = []
    for socket_type in (socket.SOCK_DGRAM, socket.SOCK_RAW):
        sock = None
        try:
            sock = socket.socket(
                socket.AF_INET, socket_type, socket.IPPROTO_ICMP
            )
            sock.setblocking(False)
            return sock
        except OSError as exc:
            if sock is not None:
                sock.close()
            errors.append(str(exc))
    raise OSError("; ".join(errors))


def write_report(report: dict) -> None:
    text = json.dumps(report, indent=2, sort_keys=True)
    print(text)
    try:
        OUTPUT_DIRECTORY.mkdir(parents=True, exist_ok=True)
        (OUTPUT_DIRECTORY / "icmp_report.json").write_text(
            text + "\n", encoding="utf-8"
        )
    except OSError as exc:
        print(f"Could not write report: {exc}")


def icmp_flood(target_ip: str, duration: int) -> None:
    """Send actual ICMP requests to loopback for a bounded duration."""
    report = {
        "target": target_ip,
        "duration_seconds": duration,
        "packets_sent": 0,
        "send_errors": 0,
        "elapsed_seconds": 0.0,
        "status": "pending",
    }

    try:
        address = ipaddress.IPv4Address(target_ip)
        if not address.is_loopback:
            raise ValueError("The benchmark endpoint must be IPv4 loopback.")
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise ValueError("Duration must be an integer.")
        if not 0 <= duration <= MAX_DURATION:
            raise ValueError(f"Duration must be between 0 and {MAX_DURATION}.")

        if duration == 0:
            report["status"] = "completed"
            write_report(report)
            return

        with open_icmp_socket() as sock:
            started = time.monotonic()
            deadline = started + duration
            interval = 1.0 / PACKETS_PER_SECOND
            maximum_attempts = math.ceil(duration * PACKETS_PER_SECOND)

            for sequence in range(maximum_attempts):
                scheduled = started + sequence * interval
                remaining = min(scheduled, deadline) - time.monotonic()
                if remaining > 0:
                    time.sleep(remaining)
                if time.monotonic() >= deadline:
                    break

                packet = create_packet(0x1234, sequence)
                try:
                    sent = sock.sendto(packet, (str(address), 0))
                    if sent == len(packet):
                        report["packets_sent"] += 1
                    else:
                        report["send_errors"] += 1
                except (BlockingIOError, InterruptedError):
                    report["send_errors"] += 1
                except OSError as exc:
                    report["send_errors"] += 1
                    report["last_error"] = str(exc)

                # Drain a bounded number of loopback responses.
                for _ in range(4):
                    try:
                        sock.recvfrom(65535)
                    except (BlockingIOError, InterruptedError):
                        break
                    except OSError:
                        break

            remaining = deadline - time.monotonic()
            if remaining > 0:
                time.sleep(remaining)
            report["elapsed_seconds"] = round(time.monotonic() - started, 6)
            report["status"] = (
                "completed"
                if report["packets_sent"]
                else "no_packets_sent"
            )
    except (ValueError, OSError) as exc:
        report["status"] = "error"
        report["error"] = str(exc)

    write_report(report)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Bounded ICMP benchmark for an IPv4 loopback endpoint."
    )
    parser.add_argument("target", nargs="?", default=DEFAULT_TARGET)
    parser.add_argument(
        "-d", "--duration", type=int, default=DEFAULT_DURATION
    )
    try:
        args = parser.parse_args()
    except SystemExit:
        return

    icmp_flood(args.target, args.duration)


if __name__ == "__main__":
    main()

import argparse
import http.client
import ipaddress
import json
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit


MAX_DURATION = 30
REQUESTS_PER_SECOND = 100


def send_requests(url, duration, log_file=None, silent=False):
    parsed = urlsplit(url)
    if parsed.scheme not in ("http", "https") or not parsed.hostname:
        raise ValueError("Expected an HTTP or HTTPS URL.")
    if parsed.username is not None or parsed.password is not None:
        raise ValueError("URL credentials are unsupported.")

    host = parsed.hostname
    if host.lower() == "localhost":
        host = "127.0.0.1"
    elif not ipaddress.ip_address(host).is_loopback:
        raise ValueError("Benchmark endpoints must use a loopback address.")

    duration = max(0, min(int(duration), MAX_DURATION))
    path = parsed.path or "/"
    if parsed.query:
        path += "?" + parsed.query

    connection_class = (
        http.client.HTTPSConnection
        if parsed.scheme == "https"
        else http.client.HTTPConnection
    )
    deadline = time.monotonic() + duration
    connection = None
    results = {"attempts": 0, "completed": 0, "statuses": {}, "errors": []}

    try:
        for _ in range(duration * REQUESTS_PER_SECOND + 1):
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break

            started = time.monotonic()
            results["attempts"] += 1
            try:
                if connection is None:
                    connection = connection_class(
                        host, port=parsed.port, timeout=min(1.0, remaining)
                    )
                connection.timeout = min(1.0, remaining)
                if connection.sock is not None:
                    connection.sock.settimeout(connection.timeout)

                connection.request("GET", path)
                response = connection.getresponse()
                status = str(response.status)
                # Bound response handling even if an endpoint streams indefinitely.
                response.read(65536)
                results["completed"] += 1
                results["statuses"][status] = results["statuses"].get(status, 0) + 1

                if not silent:
                    print(f"Request {results['attempts']}: {status}")

                connection.close()
                connection = None
            except Exception as exc:
                if len(results["errors"]) < 100:
                    results["errors"].append(str(exc))
                if connection is not None:
                    connection.close()
                    connection = None

            delay = min(
                deadline - time.monotonic(),
                1.0 / REQUESTS_PER_SECOND - (time.monotonic() - started),
            )
            if delay > 0:
                time.sleep(delay)
    finally:
        if connection is not None:
            connection.close()

    if log_file:
        destination = Path(log_file)
        if destination.is_absolute() or ".." in destination.parts:
            raise ValueError("Log paths must be relative without parent traversal.")
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(json.dumps(results, indent=2) + "\n", encoding="utf-8")

    if not silent:
        print(f"Test completed. Total requests sent: {results['completed']}")


def http_flood(target_url: str, duration: int) -> None:
    send_requests(target_url, duration, silent=True)


class BenchmarkHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        body = b"controlled benchmark endpoint\n"
        self.send_response(200)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except OSError:
            pass

    def log_message(self, format, *args):
        pass


def main():
    parser = argparse.ArgumentParser(description="Controlled local HTTP benchmark.")
    parser.add_argument("url", nargs="?", default=None)
    parser.add_argument("duration", nargs="?", type=int, default=1)
    parser.add_argument("--log-file", default="target/results.json")
    parser.add_argument("--silent", action="store_true")
    server = None
    worker = None

    try:
        args = parser.parse_args()
        Path("target").mkdir(parents=True, exist_ok=True)

        url = args.url
        if url is None:
            server = ThreadingHTTPServer(("127.0.0.1", 0), BenchmarkHandler)
            server.daemon_threads = True
            worker = threading.Thread(
                target=server.serve_forever,
                kwargs={"poll_interval": 0.05},
                daemon=True,
            )
            worker.start()
            url = f"http://127.0.0.1:{server.server_port}/benchmark"

        send_requests(url, args.duration, args.log_file, args.silent)
    except SystemExit:
        pass
    except Exception as exc:
        print(f"Benchmark finished: {exc}")
    finally:
        if server is not None:
            if worker is not None:
                server.shutdown()
            server.server_close()
        if worker is not None:
            worker.join(timeout=1.0)


if __name__ == "__main__":
    main()

"""Bounded, loopback-only DNS amplification demonstration.

Uses real UDP DNS requests and larger DNS responses against a local server.
Public-resolver flooding and source-IP spoofing are intentionally unsupported.
"""

import argparse
import ipaddress
import json
import socket
import struct
import threading
import time
from pathlib import Path

WORK_DIR = Path("target")
LOG_FILE = WORK_DIR / "dns_log.txt"
MAX_DURATION = 5
MAX_QUERIES = 100
QUERY_INTERVAL = 0.05


def log_query(domain, query, response):
    WORK_DIR.mkdir(parents=True, exist_ok=True)
    record = {"domain": domain, "query": query, "response": response}
    with LOG_FILE.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(record, sort_keys=True) + "\n")


def encode_name(domain):
    labels = domain.rstrip(".").encode("ascii").split(b".")
    if any(not label or len(label) > 63 for label in labels):
        raise ValueError("Invalid DNS domain")
    encoded = b"".join(bytes([len(label)]) + label for label in labels) + b"\0"
    if len(encoded) > 255:
        raise ValueError("DNS name is too long")
    return encoded


def make_query(domain, transaction_id, query_type=16):
    header = struct.pack("!6H", transaction_id, 0x0100, 1, 0, 0, 0)
    return header + encode_name(domain) + struct.pack("!HH", query_type, 1)


def make_response(query):
    if len(query) < 17:
        raise ValueError("Truncated DNS query")

    position = 12
    for _ in range(128):
        if position >= len(query):
            raise ValueError("Truncated DNS name")
        size = query[position]
        position += 1
        if size == 0:
            break
        if size > 63 or position + size > len(query):
            raise ValueError("Invalid DNS label")
        position += size
    else:
        raise ValueError("DNS name exceeds label limit")

    if position + 4 != len(query):
        raise ValueError("Invalid DNS question")

    query_type, query_class = struct.unpack("!HH", query[position:])
    if query_class != 1 or query_type not in (1, 16):
        raise ValueError("Unsupported DNS question")

    if query_type == 1:
        payload = socket.inet_aton("127.0.0.1")
    else:
        payload = b"".join(bytes([200]) + b"x" * 200 for _ in range(4))

    header = query[:2] + struct.pack("!5H", 0x8180, 1, 1, 0, 0)
    answer = struct.pack("!HHHIH", 0xC00C, query_type, 1, 60, len(payload))
    return header + query[12:] + answer + payload


class LocalDNSServer:
    def __init__(self, host):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            self.socket.bind((host, 0))
            self.socket.settimeout(0.1)
        except Exception:
            self.socket.close()
            raise
        self.address = self.socket.getsockname()
        self.stop = threading.Event()
        self.thread = threading.Thread(target=self.serve, daemon=True)

    def serve(self):
        deadline = time.monotonic() + MAX_DURATION + 2
        for _ in range(200):
            if self.stop.is_set() or time.monotonic() >= deadline:
                break
            try:
                query, peer = self.socket.recvfrom(4096)
                self.socket.sendto(make_response(query), peer)
            except socket.timeout:
                continue
            except ValueError:
                continue
            except OSError:
                break

    def __enter__(self):
        self.thread.start()
        return self

    def __exit__(self, *unused):
        self.stop.set()
        self.thread.join(timeout=0.5)
        self.socket.close()


def exchange(client, server, domain, transaction_id, query_type):
    query = make_query(domain, transaction_id, query_type)
    client.sendto(query, server)
    response, peer = client.recvfrom(4096)
    if peer != server or response[:2] != query[:2]:
        raise ValueError("Unexpected DNS response")
    if len(response) < 12 or not response[2] & 0x80:
        raise ValueError("Invalid DNS response")
    return query, response


def dns_amplification(target_ip: str = "127.0.0.1", duration: int = 1) -> None:
    """Measure DNS response expansion on a controlled loopback UDP endpoint."""
    address = ipaddress.ip_address(target_ip)
    if address.version != 4 or not address.is_loopback:
        raise ValueError("The controlled endpoint must be an IPv4 loopback address")

    duration = max(0, min(int(duration), MAX_DURATION))
    summary = {
        "queries": 0,
        "failures": 0,
        "request_bytes": 0,
        "response_bytes": 0,
    }

    with LocalDNSServer(str(address)) as server:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as client:
            client.bind((str(address), 0))
            client.settimeout(0.2)

            # Preserve domain-resolution coverage using the controlled DNS server.
            query, response = exchange(client, server.address, "example.test", 1, 1)
            resolved = socket.inet_ntoa(response[-4:])
            log_query("example.test", "A", {"address": resolved})

            deadline = time.monotonic() + duration
            for index in range(MAX_QUERIES):
                if time.monotonic() >= deadline:
                    break
                started = time.monotonic()
                try:
                    query, response = exchange(
                        client, server.address, "example.test", index + 2, 16
                    )
                    summary["queries"] += 1
                    summary["request_bytes"] += len(query)
                    summary["response_bytes"] += len(response)
                    log_query(
                        "example.test",
                        "TXT",
                        {
                            "request_bytes": len(query),
                            "response_bytes": len(response),
                        },
                    )
                except (OSError, ValueError) as exc:
                    summary["failures"] += 1
                    log_query("example.test", "TXT", {"error": str(exc)})

                remaining = deadline - time.monotonic()
                delay = QUERY_INTERVAL - (time.monotonic() - started)
                if remaining > 0 and delay > 0:
                    time.sleep(min(delay, remaining))

    request_bytes = summary["request_bytes"]
    summary["payload_amplification"] = (
        round(summary["response_bytes"] / request_bytes, 3)
        if request_bytes
        else 0.0
    )
    WORK_DIR.mkdir(parents=True, exist_ok=True)
    (WORK_DIR / "summary.json").write_text(
        json.dumps(summary, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(json.dumps(summary, sort_keys=True))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--target-ip", default="127.0.0.1")
    parser.add_argument("--duration", type=int, default=1)
    try:
        args, _ = parser.parse_known_args()
        dns_amplification(args.target_ip, args.duration)
    except SystemExit:
        return
    except Exception as exc:
        print(json.dumps({"error": str(exc)}, sort_keys=True))


if __name__ == "__main__":
    main()

