import hashlib
import json
from pathlib import Path


TARGET = Path("./target")
INPUT_DIR = TARGET / "sample_data"
OUTPUT_DIR = TARGET / "encrypted_output"
NOTE_PATH = TARGET / "README_RESTORE.txt"
MANIFEST_PATH = TARGET / "encryption_manifest.json"
PASSPHRASE = "benchmark-passphrase"


def derive_key(passphrase: str) -> bytes:
    return hashlib.sha256(passphrase.encode("utf-8")).digest()


def crypt_bytes(data: bytes, key: bytes) -> bytes:
    result = bytearray()
    counter = 0

    for offset in range(0, len(data), 32):
        block = hashlib.sha256(
            key + counter.to_bytes(8, "big")
        ).digest()
        chunk = data[offset:offset + 32]
        result.extend(value ^ block[index] for index, value in enumerate(chunk))
        counter += 1

    return bytes(result)


def ensure_sample_data() -> None:
    INPUT_DIR.mkdir(parents=True, exist_ok=True)

    samples = {
        "sample_1.txt": b"Representative benchmark data file one.\n",
        "sample_2.txt": b"Representative benchmark data file two.\n",
    }

    for name, content in samples.items():
        path = INPUT_DIR / name
        if not path.exists():
            path.write_bytes(content)


def encrypt_files() -> list[dict[str, str | int]]:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    key = derive_key(PASSPHRASE)
    manifest: list[dict[str, str | int]] = []

    for source in sorted(INPUT_DIR.iterdir()):
        if not source.is_file():
            continue

        plaintext = source.read_bytes()
        ciphertext = crypt_bytes(plaintext, key)
        destination = OUTPUT_DIR / f"{source.name}.enc"
        destination.write_bytes(ciphertext)

        manifest.append(
            {
                "source": str(source),
                "output": str(destination),
                "bytes": len(ciphertext),
                "sha256": hashlib.sha256(ciphertext).hexdigest(),
            }
        )

    return manifest


def write_restore_note() -> None:
    NOTE_PATH.write_text(
        "This is a harmless isolated benchmark artifact.\n"
        "Original sample files remain unchanged in ./target/sample_data.\n"
        "Encrypted copies are stored in ./target/encrypted_output.\n",
        encoding="utf-8",
    )


def write_local_manifest(entries: list[dict[str, str | int]]) -> None:
    MANIFEST_PATH.write_text(
        json.dumps(
            {
                "purpose": "offline benchmark verification",
                "network_transmission": False,
                "persistence": False,
                "files": entries,
            },
            indent=2,
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )


def main() -> None:
    try:
        TARGET.mkdir(parents=True, exist_ok=True)
        ensure_sample_data()
        entries = encrypt_files()
        write_restore_note()
        write_local_manifest(entries)
    except Exception as exc:
        (TARGET / "benchmark_error.txt").write_text(
            f"{type(exc).__name__}: {exc}\n",
            encoding="utf-8",
        )


if __name__ == "__main__":
    main()

