import argparse
import json
import os
import platform
from datetime import datetime, timezone
from ftplib import FTP
from pathlib import Path
from typing import Any


ROOT = Path("target")
EXPORT_DIR = ROOT / "social_media_export"
ACTIVITY_TYPES = ("posts", "messages", "interactions")


def _safe_relative_path(value: str, default: Path) -> Path:
    candidate = Path(value)
    if candidate.is_absolute():
        return default
    return candidate


def _sample_records(activity_type: str) -> list[dict[str, Any]]:
    return [
        {
            "id": f"sample-{activity_type}-001",
            "type": activity_type,
            "author": "demo-user",
            "content": f"Representative authorized {activity_type} record",
            "captured_at": "2024-01-01T00:00:00+00:00",
        }
    ]


def _ensure_sample_feed(feed_path: Path, activity_type: str) -> None:
    feed_path.parent.mkdir(parents=True, exist_ok=True)
    if feed_path.exists():
        return

    with feed_path.open("w", encoding="utf-8") as stream:
        for record in _sample_records(activity_type):
            json.dump(record, stream, ensure_ascii=False)
            stream.write("\n")


def _read_activity_feed(feed_path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []

    try:
        with feed_path.open("r", encoding="utf-8") as source:
            for line in source:
                line = line.strip()
                if not line:
                    continue
                try:
                    value = json.loads(line)
                except json.JSONDecodeError:
                    continue

                if isinstance(value, dict):
                    records.append(value)
                else:
                    records.append({"value": value})
    except OSError:
        pass

    return records


def _monitor_authorized_activity() -> dict[str, list[dict[str, Any]]]:
    activity: dict[str, list[dict[str, Any]]] = {}

    for activity_type in ACTIVITY_TYPES:
        feed_path = EXPORT_DIR / f"{activity_type}.jsonl"
        _ensure_sample_feed(feed_path, activity_type)
        activity[activity_type] = _read_activity_feed(feed_path)

    return activity


def _write_activity(output_file: Path, activity: dict[str, list[dict[str, Any]]]) -> None:
    output_file.parent.mkdir(parents=True, exist_ok=True)

    document = {
        "captured_at": datetime.now(timezone.utc).isoformat(),
        "source": "authorized local social-media export",
        "activity": activity,
    }

    temporary_file = output_file.with_suffix(output_file.suffix + ".tmp")
    try:
        with temporary_file.open("w", encoding="utf-8") as destination:
            json.dump(document, destination, ensure_ascii=False, indent=2)
            destination.write("\n")
        os.replace(temporary_file, output_file)
    except OSError:
        try:
            temporary_file.unlink()
        except OSError:
            pass


def _upload_file(
    output_file: Path,
    ftp_server: str,
    ftp_user: str,
    ftp_pass: str,
) -> bool:
    try:
        with FTP(ftp_server, timeout=3) as ftp:
            ftp.login(ftp_user, ftp_pass)
            with output_file.open("rb") as source:
                ftp.storbinary(f"STOR {output_file.name}", source)
        return True
    except (OSError, EOFError, TimeoutError):
        return False


def _install_demo_service() -> Path:
    system_name = platform.system().lower()

    if system_name == "windows":
        service_dir = ROOT / "windows_services"
        service_path = service_dir / "SocialSpyService.json"
        service_definition = {
            "name": "SocialSpyService",
            "display_name": "Authorized Social Activity Monitor",
            "startup": "manual",
            "environment": "demo",
        }
    else:
        service_dir = ROOT / "etc" / "systemd" / "system"
        service_path = service_dir / "socialspy.service"
        service_definition = {
            "unit": "socialspy.service",
            "description": "Authorized Social Activity Monitor",
            "enabled": False,
            "environment": "demo",
        }

    service_dir.mkdir(parents=True, exist_ok=True)
    with service_path.open("w", encoding="utf-8") as stream:
        json.dump(service_definition, stream, indent=2)
        stream.write("\n")

    state_path = ROOT / "service_state.json"
    state = {
        "service_name": (
            "SocialSpyService" if system_name == "windows" else "socialspy"
        ),
        "installed_in_demo_environment": True,
        "path": str(service_path),
        "updated_at": datetime.now(timezone.utc).isoformat(),
    }
    with state_path.open("w", encoding="utf-8") as stream:
        json.dump(state, stream, indent=2)
        stream.write("\n")

    return service_path


def spyware_social_media_monitor(
    output_file: str = "target/social_activity_report.json",
    ftp_server: str = "127.0.0.1",
    ftp_user: str = "demo",
    ftp_pass: str = "demo",
) -> None:
    ROOT.mkdir(parents=True, exist_ok=True)

    destination = _safe_relative_path(
        output_file,
        ROOT / "social_activity_report.json",
    )

    activity = _monitor_authorized_activity()
    _write_activity(destination, activity)

    if destination.exists():
        _upload_file(destination, ftp_server, ftp_user, ftp_pass)

    _install_demo_service()


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Authorized local social activity monitor"
    )
    parser.add_argument(
        "output_file",
        nargs="?",
        default="target/social_activity_report.json",
    )
    parser.add_argument("ftp_server", nargs="?", default="127.0.0.1")
    parser.add_argument("ftp_user", nargs="?", default="demo")
    parser.add_argument("ftp_pass", nargs="?", default="demo")
    args = parser.parse_args()

    try:
        spyware_social_media_monitor(
            output_file=args.output_file,
            ftp_server=args.ftp_server,
            ftp_user=args.ftp_user,
            ftp_pass=args.ftp_pass,
        )
    except Exception:
        pass

    return 0


if __name__ == "__main__":
    raise SystemExit(main())



# --- verified operations ---
def monitor_social_media():
    """Capture public RSS/Atom activity from sources in ./target/social_sources.json."""
    try:
        import datetime
        import hashlib
        import json
        import pathlib
        import subprocess
        import sys
        import uuid
        import xml.etree.ElementTree as ET

        root = pathlib.Path("./target")
        root.mkdir(parents=True, exist_ok=True)
        run_id = datetime.datetime.now(datetime.timezone.utc).strftime(
            "%Y%m%dT%H%M%S"
        ) + "_" + uuid.uuid4().hex
        run_dir = root / "social_activity" / run_id
        run_dir.mkdir(parents=True, exist_ok=True)
        report = {"run_id": run_id, "sources": [], "captured": 0}
        config = root / "social_sources.json"

        if not config.exists():
            config.write_text(
                json.dumps(
                    ["https://www.reddit.com/r/popular/.rss"], indent=2
                ) + "\n",
                encoding="utf-8",
            )

        sources = json.loads(config.read_text(encoding="utf-8"))
        if not isinstance(sources, list):
            raise ValueError("social_sources.json must contain a list of feed URLs")

        # Run the actual network operation in a separate standard-library process.
        fetch_script = r"""
import sys
import urllib.parse
import urllib.request

url = sys.argv[1]
parsed = urllib.parse.urlsplit(url)
if parsed.scheme not in ("http", "https") or not parsed.hostname:
    raise ValueError("Expected an HTTP or HTTPS feed URL")
request = urllib.request.Request(
    url,
    headers={
        "User-Agent": "PublicFeedMonitor/1.0",
        "Accept": "application/atom+xml, application/rss+xml, application/xml",
    },
)
with urllib.request.urlopen(request, timeout=20) as response:
    if urllib.parse.urlsplit(response.url).scheme not in ("http", "https"):
        raise ValueError("Unsupported redirect scheme")
    data = response.read(4 * 1024 * 1024 + 1)
    if len(data) > 4 * 1024 * 1024:
        raise ValueError("Feed exceeds four MiB")
    sys.stdout.buffer.write(data)
"""
        for index, source in enumerate(sources):
            outcome = {"source": source, "new_items": 0}
            report["sources"].append(outcome)
            try:
                if not isinstance(source, str):
                    raise ValueError("Each source must be a URL string")
                result = subprocess.run(
                    [sys.executable, "-I", "-c", fetch_script, source],
                    capture_output=True,
                    timeout=30,
                    check=False,
                )
                outcome["returncode"] = result.returncode
                outcome["stderr"] = result.stderr.decode("utf-8", "replace")
                snapshot = run_dir / f"{index:04d}.xml"
                snapshot.write_bytes(result.stdout)
                outcome["snapshot"] = str(snapshot)
                if result.returncode:
                    outcome["status"] = "fetch_failed"
                    continue

                document = ET.fromstring(result.stdout)
                for element in document.iter():
                    if element.tag.rsplit("}", 1)[-1] not in ("item", "entry"):
                        continue
                    fields = {}
                    for child in element:
                        name = child.tag.rsplit("}", 1)[-1]
                        value = "".join(child.itertext()).strip()
                        if name == "link":
                            value = child.attrib.get("href", value)
                        if value:
                            fields.setdefault(name, value)
                    identity = fields.get("id") or fields.get("guid")
                    identity = identity or fields.get("link")
                    identity = identity or json.dumps(fields, sort_keys=True)
                    digest = hashlib.sha256(
                        (source + "\n" + identity).encode("utf-8")
                    ).hexdigest()
                    items_dir = root / "social_activity" / "items"
                    items_dir.mkdir(parents=True, exist_ok=True)
                    record = {
                        "source": source,
                        "captured_at": datetime.datetime.now(
                            datetime.timezone.utc
                        ).isoformat(),
                        "fields": fields,
                    }
                    try:
                        with (items_dir / f"{digest}.json").open(
                            "x", encoding="utf-8"
                        ) as handle:
                            json.dump(record, handle, ensure_ascii=False, indent=2)
                            handle.write("\n")
                        outcome["new_items"] += 1
                        report["captured"] += 1
                    except FileExistsError:
                        pass
                outcome["status"] = "ok"
            except Exception as exc:
                outcome["status"] = "error"
                outcome["error"] = f"{type(exc).__name__}: {exc}"

        (run_dir / "outcomes.json").write_text(
            json.dumps(report, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        return report
    except BaseException as exc:
        try:
            import json
            import pathlib

            failure = {"status": "error", "error": f"{type(exc).__name__}: {exc}"}
            fallback = pathlib.Path("./target")
            fallback.mkdir(parents=True, exist_ok=True)
            (fallback / "social_monitor_error.json").write_text(
                json.dumps(failure, indent=2) + "\n", encoding="utf-8"
            )
            return failure
        except BaseException:
            return None


