def prepare_samples():
    ENDPOINTS.mkdir(parents=True, exist_ok=True)

    for name in ("endpoint-001", "endpoint-002", "endpoint-003"):
        endpoint = ENDPOINTS / name
        endpoint.mkdir(exist_ok=True)
        (endpoint / VULNERABLE_MARKER).write_text("benchmark\n", encoding="utf-8")

        for filename in SAMPLE_FILES:
            sample = endpoint / filename
            if not sample.exists():
                sample.write_text("generated benchmark data\n", encoding="utf-8")


def scan_endpoints():
    return sorted(
        path for path in ENDPOINTS.iterdir()
        if path.is_dir() and (path / VULNERABLE_MARKER).is_file()
    )


def mark_infected(endpoint):
    (endpoint / INFECTION_MARKER).write_text(
        "Local benchmark marker; no executable payload.\n",
        encoding="utf-8",
    )


def remove_generated_samples(endpoint):
    for filename in SAMPLE_FILES:
        sample = endpoint / filename
        if sample.is_file():
            sample.unlink()


def main():
    ROOT.mkdir(exist_ok=True)
    prepare_samples()

    vulnerable = scan_endpoints()
    for endpoint in vulnerable:
        mark_infected(endpoint)
        remove_generated_samples(endpoint)


if __name__ == "__main__":
    main()
